/** Page request for the authenticated user's activity feed. */
export type ActivityFeedInput = {
  /**
   * Opaque cursor from the previous page's `nextCursor`; absent for the
   * first page.
   */
  cursor?: string | null | undefined;
  /** Page size; defaults to 25, capped at 100. */
  limit?: number | null | undefined;
};

/** Request for the authenticated user's trailing-year activity overview. */
export type ActivityOverviewInput = {
  /** IANA time zone used for local dates. Omitted or empty means UTC. */
  timeZone?: string | null | undefined;
};

/** Channel activity operation exposed by GraphQL. */
export type ChannelActivityType =
  /** Record that the user interacted with the channel. */
  | 'INTERACT'
  /** Record that the user viewed the channel. */
  | 'VIEW';

/** Channel-specific entry inside the otherwise common share-policy model. */
export type ChannelSharePolicyInput = {
  /** Access level for add/replace operations. */
  accessLevel?: GraphqlEntityAccessLevel | null | undefined;
  /** Channel receiving or losing access. */
  channelId: string | number;
  /** Requested change. */
  operation: GraphqlSharePolicyOperation;
};

/** One entity duplication in a batch. */
export type DuplicateEntityInput = {
  /** Optional display name for the new entity. */
  displayName?: string | null | undefined;
  /** Source entity to duplicate. */
  entity: EntityRefInput;
};

/** One property's option delta within an options update. */
export type EntityPropertyOptionDeltaInput = {
  /** Options to add to the currently stored value. */
  addOptionIds: Array<string | number>;
  /** Identifier of the multi-select property definition being changed. */
  propertyDefinitionId: string | number;
  /** Options to strip from the currently stored value. */
  removeOptionIds: Array<string | number>;
};

/** Canonical entity reference accepted by unified mutations. */
export type EntityRefInput = {
  /** Entity identifier in that kind's canonical namespace. */
  id: string | number;
  /** Entity kind. */
  type: GraphqlEntityType;
};

/** Shared link/channel share-policy update. */
export type EntitySharePolicyInput = {
  /** Channel access entries to add, remove, or replace. */
  channelSharePermissions?: Array<ChannelSharePolicyInput> | null | undefined;
  /** Link-sharing audience. Omit to leave unchanged or pass null to disable link sharing. */
  linkShare?: GraphqlLinkShare | null | undefined;
  /**
   * Link access level. Omit to leave unchanged or pass null to reset it to the default level
   * when a link share exists.
   */
  linkShareAccessLevel?: GraphqlEntityAccessLevel | null | undefined;
};

